solution:
import { DocumentNode, ApolloError, useMutation as useApolloMutation } from '@apollo/client';
import { useState } from 'react';

type UseMutationOptions<TData, TVariables> = {
  mutation: DocumentNode;
  optimisticResponse?: (variables: TVariables) => TData;
  onCompleted?: (data: TData) => void;
  onError?: (error: ApolloError) => void;
};

export function useMutation<TData, TVariables>(
  options: UseMutationOptions<TData, TVariables>
): [
  (variables: TVariables) => Promise<TData>,
  { loading: boolean; error?: ApolloError }
] {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<ApolloError | undefined>();

  const [executeMutation] = useApolloMutation(options.mutation, {
    optimisticResponse: options.optimisticResponse
      ? { __typename: 'Mutation', ...options.optimisticResponse }
      : undefined,
    onCompleted: (data) => {
      setLoading(false);
      setError(undefined);
      options.onCompleted?.(data);
    },
    onError: (apolloError) => {
      setLoading(false);
      setError(apolloError);
      options.onError?.(apolloError);
    },
  });

  const mutationFn = async (variables: TVariables): Promise<TData> => {
    setLoading(true);
    setError(undefined);

    try {
      const result = await executeMutation({ variables });
      return result.data;
    } catch (err) {
      const apolloError = err as ApolloError;
      setError(apolloError);
      throw apolloError;
    }
  };

  return [mutationFn, { loading, error }];
}

description.en:
Implement a DataLoader class that batches database queries and prevents N+1 query problems in GraphQL resolvers. An N+1 problem is one query for a list plus one more query per item in that list. DataLoader should collect requests during a single event loop iteration and batch them together.

**Requirements:**

- Create a DataLoader class that accepts a batch loading function
- Queue individual load requests and batch them together
- Resolve promises for each individual request from the batch result
- Clear the batch queue after processing
- Support cache key generation for deduplication
- Handle errors gracefully

**Class signature:**

```typescript
type BatchLoadFn<K, V> = (keys: K[]) => Promise<V[]>;

class DataLoader<K, V> {
  constructor(batchLoadFn: BatchLoadFn<K, V>, options?: { cache?: boolean });
  load(key: K): Promise<V>;
  loadMany(keys: K[]): Promise<(V | Error)[]>;
  clear(key: K): this;
  clearAll(): this;
}
```

**Example:**

```typescript
const userLoader = new DataLoader(async (userIds: number[]) => {
  console.log(`Loading users: ${userIds}`);
  return db.query('SELECT * FROM users WHERE id IN (?)', [userIds]);
});

// In a resolver:
const user1 = await userLoader.load(1);
const user2 = await userLoader.load(2);
const user1Again = await userLoader.load(1); // returns the cached promise

// Result: a single database query for users [1, 2] instead of 3 queries
```

**Edge cases:**

- Several loads of the same key, which should use the cached promise
- An error in the batch loading function, which should reject all pending loads
- Mixing load() and loadMany() calls
- Clearing the cache between operations

