type BatchLoadFn<K, V> = (keys: K[]) => Promise<V[]>;

interface DataLoaderOptions {
  cache?: boolean;
}

export class DataLoader<K, V> {
  private batchLoadFn: BatchLoadFn<K, V>;
  private cache: Map<K, Promise<V>>;
  private queue: K[] = [];
  private batchScheduled = false;
  private cacheEnabled: boolean;
  private pending: Map<K, { resolve: (v: V) => void; reject: (e: Error) => void }[]> = new Map();

  constructor(batchLoadFn: BatchLoadFn<K, V>, options?: DataLoaderOptions) {
    this.batchLoadFn = batchLoadFn;
    this.cache = new Map();
    this.cacheEnabled = options?.cache !== false;
  }

  load(key: K): Promise<V> {
    // Return cached promise if available
    if (this.cacheEnabled && this.cache.has(key)) {
      return this.cache.get(key)!;
    }

    // Create promise for this key
    const promise = new Promise<V>((resolve, reject) => {
      if (!this.pending.has(key)) {
        this.pending.set(key, []);
        this.queue.push(key);
      }
      this.pending.get(key)!.push({ resolve, reject });
    });

    // Cache the promise
    if (this.cacheEnabled) {
      this.cache.set(key, promise);
    }

    // Schedule batch processing
    if (!this.batchScheduled) {
      this.scheduleBatch();
    }

    return promise;
  }

  loadMany(keys: K[]): Promise<(V | Error)[]> {
    return Promise.all(
      keys.map((key) =>
        this.load(key)
          .then((value) => value)
          .catch((error) => error)
      )
    );
  }

  clear(key: K): this {
    this.cache.delete(key);
    return this;
  }

  clearAll(): this {
    this.cache.clear();
    return this;
  }

  private scheduleBatch(): void {
    this.batchScheduled = true;
    Promise.resolve().then(() => this.processBatch());
  }

  private processBatch(): void {
    const queue = this.queue;
    this.queue = [];
    this.batchScheduled = false;

    if (queue.length === 0) return;

    // Remove duplicates while preserving order
    const uniqueQueue = Array.from(new Map(queue.map((k) => [k, k])).values());

    this.batchLoadFn(uniqueQueue)
      .then((values) => {
        uniqueQueue.forEach((key, index) => {
          const value = values[index];
          const callbacks = this.pending.get(key) || [];
          callbacks.forEach((cb) => cb.resolve(value));
          this.pending.delete(key);
        });
      })
      .catch((error) => {
        uniqueQueue.forEach((key) => {
          const callbacks = this.pending.get(key) || [];
          callbacks.forEach((cb) => cb.reject(error));
          this.pending.delete(key);
        });
      });
  }
}

description.en:
Implement cursor-based pagination for GraphQL queries that efficiently handles large datasets. Cursor pagination uses encoded identifiers to mark positions in data instead of relying on an offset, which makes it a good fit for real-time data.

**Requirements:**

- Create a pagination interface with cursor, edges, and pageInfo
- Implement cursor encoding and decoding (base64)
- Support forward (first/after) and backward (last/before) pagination
- Calculate hasNextPage and hasPreviousPage correctly
- Handle edge cases: empty results, a single page, requesting more items than available
- Return a consistent cursor format

**Type definitions:**

```typescript
interface PaginationArgs {
  first?: number;
  after?: string;
  last?: number;
  before?: string;
}

interface Edge<T> {
  cursor: string;
  node: T;
}

interface PageInfo {
  startCursor: string | null;
  endCursor: string | null;
  hasNextPage: boolean;
  hasPreviousPage: boolean;
}

interface Connection<T> {
  edges: Edge<T>[];
  pageInfo: PageInfo;
  totalCount: number;
}

function paginate<T>(
  items: T[],
  args: PaginationArgs,
  getCursorValue: (item: T) => string | number
): Connection<T>;
```

**Example:**

```typescript
const users = [
  { id: 1, name: 'Alice' },
  { id: 2, name: 'Bob' },
  { id: 3, name: 'Charlie' },
  { id: 4, name: 'David' },
];

const result = paginate(users, { first: 2 }, (user) => user.id);
// Returns:
// {
//   edges: [
//     { cursor: 'MQ==', node: { id: 1, name: 'Alice' } },
//     { cursor: 'Mg==', node: { id: 2, name: 'Bob' } }
//   ],
//   pageInfo: {
//     startCursor: 'MQ==',
//     endCursor: 'Mg==',
//     hasNextPage: true,
//     hasPreviousPage: false
//   },
//   totalCount: 4
// }

// Next page, with the after cursor
const nextPage = paginate(users, { first: 2, after: 'Mg==' }, (user) => user.id);
// Returns items 3-4 with hasNextPage: false
```

**Edge cases:**

- An empty dataset
- Requesting more items than available
- An invalid cursor value
- Both first and last specified, so one of them has to be picked
- A cursor pointing beyond the dataset boundaries

